class Solution {
public:
    vector<int> gridIllumination(int n, vector<vector<int>>& lamps, vector<vector<int>>& queries) {
        unordered_map<int,int> rows, cols, diag1, diag2;
        unordered_set<long long> lampSet;

        for (auto& l : lamps) {
            int r = l[0], c = l[1];
            long long key = (long long)r * n + c;
            if (lampSet.count(key)) continue;
            lampSet.insert(key);
            rows[r]++;
            cols[c]++;
            diag1[r - c]++;
            diag2[r + c]++;
        }

        vector<int> ans;
        int dr[] = {-1, -1, -1, 0, 0, 0, 1, 1, 1};
        int dc[] = {-1, 0, 1, -1, 0, 1, -1, 0, 1};

        for (auto& q : queries) {
            int r = q[0], c = q[1];
            bool illum = rows[r] > 0 || cols[c] > 0 || diag1[r - c] > 0 || diag2[r + c] > 0;
            ans.push_back(illum ? 1 : 0);

            for (int d = 0; d < 9; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= n || nc < 0 || nc >= n) continue;
                long long key = (long long)nr * n + nc;
                if (lampSet.count(key)) {
                    lampSet.erase(key);
                    rows[nr]--;
                    cols[nc]--;
                    diag1[nr - nc]--;
                    diag2[nr + nc]--;
                }
            }
        }

        return ans;
    }
};
